def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    return float(v) if v is not None and math.isfinite(v) and v > 0 else 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x * r ** 3
            weight += x
    return float(4.0 * math.pi * total / (3.0 * weight * v)) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', [])
    if not sites:
        return 0.0
    props = s.get('element_properties', {})
    radii = [props.get(t.get('element'), {}).get('covalent_radius_A') for t in sites]
    closest = [math.inf for t in sites]
    for b in s.get('neighbors', []):
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        ri, rj = radii[i], radii[j]
        if d is not None and d > 0 and ri is not None and rj is not None and ri > 0 and rj > 0:
            q = d / (ri + rj)
            if math.isfinite(q) and q < closest[i]:
                closest[i] = q
    total = 0.0
    weight = 0.0
    for i, t in enumerate(sites):
        w = t.get('occupancy', 1.0)
        if w is not None and w > 0 and math.isfinite(closest[i]):
            total += w * closest[i]
            weight += w
    return float(total / weight) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', [])
    if not sites:
        return 0.0
    nearest = [math.inf for t in sites]
    for b in s.get('neighbors', []):
        d = b.get('distance_A')
        if d is not None and d > 0 and d < nearest[b['i']]:
            nearest[b['i']] = d
    total = 0.0
    square = 0.0
    weight = 0.0
    for i, t in enumerate(sites):
        w = t.get('occupancy', 1.0)
        if w is not None and w > 0 and math.isfinite(nearest[i]):
            total += w * nearest[i]
            square += w * nearest[i] ** 2
            weight += w
    if weight <= 0 or total <= 0:
        return 0.0
    mean = total / weight
    return float(math.sqrt(max(0.0, square / weight - mean * mean)) / mean)

def feature(s):
    sites = s.get('sites', [])
    if not sites:
        return 0.0
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    nearest = [math.inf for t in sites]
    bonds = s.get('neighbors', [])
    for b in bonds:
        d = b.get('distance_A')
        if d is not None and d > 0 and occ[b['j']] > 0 and d < nearest[b['i']]:
            nearest[b['i']] = d
    coord = [0.0 for t in sites]
    for b in bonds:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and math.isfinite(nearest[i]) and d <= 1.8 * nearest[i]:
            coord[i] += occ[j] * math.exp(1.0 - (d / nearest[i]) ** 6)
    weight = sum(occ)
    return float(sum(w * c for w, c in zip(occ, coord)) / weight) if weight > 0 else 0.0

