    coord = [0.0 for t in sites]
    for b in bonds:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and math.isfinite(nearest[i]) and d <= 1.8 * nearest[i]:
            coord[i] += occ[j] * math.exp(1.0 - (d / nearest[i]) ** 6)
    weight = sum(occ)
