def feature(s):
    sites = s.get('sites', [])
    if not sites:
        return 0.0
    props = s.get('element_properties', {})
    en = [props.get(t.get('element'), {}).get('eneg') for t in sites]
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    nearest = [math.inf for t in sites]
    bonds = s.get('neighbors', [])
    for b in bonds:
        d = b.get('distance_A')
        if d is not None and d > 0 and occ[b['j']] > 0 and d < nearest[b['i']]:
            nearest[b['i']] = d
    total = 0.0
    for b in bonds:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and math.isfinite(nearest[i]) and d <= 1.3 * nearest[i]:
            if en[i] is not None and en[j] is not None and math.isfinite(en[i]) and math.isfinite(en[j]):
                total += occ[i] * occ[j] * (en[i] - en[j]) ** 2 / d
    weight = sum(occ)
    return float(total / (2.0 * weight)) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', [])
    if not sites:
        return 0.0
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    nearest = [math.inf for t in sites]
    bonds = s.get('neighbors', [])
    for b in bonds:
        d = b.get('distance_A')
        if d is not None and d > 0 and occ[b['j']] > 0 and d < nearest[b['i']]:
            nearest[b['i']] = d
    unlike = 0.0
    total = 0.0
    for b in bonds:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and math.isfinite(nearest[i]) and d <= 1.3 * nearest[i]:
            w = occ[i] * occ[j]
            total += w
            if sites[i].get('element') != sites[j].get('element'):
                unlike += w
    fractions = [x for x in s.get('composition', {}).values() if x is not None and x > 0 and math.isfinite(x)]
    norm = sum(fractions)
    if total <= 0 or norm <= 0:
        return 0.0
    random_unlike = 1.0 - sum((x / norm) ** 2 for x in fractions)
    return float(unlike / total - random_unlike)

def feature(s):
    sites = s.get('sites', [])
    if not sites:
        return 0.0
    props = s.get('element_properties', {})
    en = [props.get(t.get('element'), {}).get('eneg') for t in sites]
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    nearest = [math.inf for t in sites]
    bonds = s.get('neighbors', [])
    for b in bonds:
        d = b.get('distance_A')
        if d is not None and d > 0 and occ[b['j']] > 0 and d < nearest[b['i']]:
            nearest[b['i']] = d
    selected = 0.0
    total = 0.0
    for b in bonds:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and math.isfinite(nearest[i]) and d <= 1.3 * nearest[i]:
            if en[i] is not None and en[j] is not None and math.isfinite(en[i]) and math.isfinite(en[j]):
                w = occ[i] * occ[j]
                total += w
                if sites[i].get('element') == sites[j].get('element') and en[i] >= 2.5:
                    selected += w
    return float(selected / total) if total > 0 else 0.0

def feature(s):
    props = s.get('element_properties', {})
    values = []
    for e, x in s.get('composition', {}).items():
        p = props.get(e, {})
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if x is not None and x > 0 and ion is not None and affinity is not None and math.isfinite(ion) and math.isfinite(affinity) and ion > affinity:
            values += [(x, (ion + affinity) / 2.0, max(0.5, ion - affinity))]
    weight = sum(x for x, chi, eta in values)
    inverse_weight = sum(x / eta for x, chi, eta in values)
    if weight <= 0 or inverse_weight <= 0:
        return 0.0
    center = sum(x * chi / eta for x, chi, eta in values) / inverse_weight
    return float(sum(x * (chi - center) ** 2 / eta for x, chi, eta in values) / weight)

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        valence = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and valence is not None and math.isfinite(valence) and valence >= 0:
            total += x * valence
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0
